CREATE TABLE IF NOT EXISTS plans (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text UNIQUE NOT NULL, name text NOT NULL, description text NOT NULL, active boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS prices (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), plan_id uuid REFERENCES plans(id), product_type text NOT NULL, amount_paise integer NOT NULL CHECK (amount_paise >= 0), currency text NOT NULL DEFAULT 'INR', interval text, metadata jsonb NOT NULL DEFAULT '{}', active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS subscriptions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), plan_id uuid NOT NULL REFERENCES plans(id), provider_subscription_id text UNIQUE, status text NOT NULL, current_period_end timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS purchases (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), price_id uuid NOT NULL REFERENCES prices(id), provider_order_id text UNIQUE, amount_paise integer NOT NULL, currency text NOT NULL DEFAULT 'INR', status text NOT NULL DEFAULT 'created', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS payments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), purchase_id uuid NOT NULL REFERENCES purchases(id), provider_payment_id text UNIQUE, provider_signature text, amount_paise integer NOT NULL, status text NOT NULL, paid_at timestamptz);
CREATE TABLE IF NOT EXISTS entitlements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), entitlement_key text NOT NULL, source_type text NOT NULL, source_id uuid, valid_from timestamptz NOT NULL DEFAULT now(), valid_until timestamptz, UNIQUE(user_id, entitlement_key, source_id));
CREATE TABLE IF NOT EXISTS coupons (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text UNIQUE NOT NULL, discount_percent integer CHECK (discount_percent BETWEEN 1 AND 100), active boolean NOT NULL DEFAULT true, expires_at timestamptz);
CREATE TABLE IF NOT EXISTS refunds (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), payment_id uuid NOT NULL REFERENCES payments(id), provider_refund_id text UNIQUE, amount_paise integer NOT NULL, status text NOT NULL DEFAULT 'requested', reason text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS invoices (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), payment_id uuid REFERENCES payments(id), invoice_number text UNIQUE NOT NULL, amount_paise integer NOT NULL, currency text NOT NULL DEFAULT 'INR', issued_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS webhook_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), provider text NOT NULL, provider_event_id text UNIQUE NOT NULL, event_type text NOT NULL, payload jsonb NOT NULL, processed_at timestamptz, status text NOT NULL DEFAULT 'received');
INSERT INTO plans (code, name, description) VALUES ('free', 'Free', 'Core support and sample content.'), ('plus', 'Plus', 'All notes and practice sets.'), ('pro', 'Pro', 'Plus with one mock interview each month.') ON CONFLICT (code) DO NOTHING;
INSERT INTO prices (plan_id, product_type, amount_paise, interval) SELECT id, 'subscription', 0, 'month' FROM plans WHERE code = 'free' AND NOT EXISTS (SELECT 1 FROM prices WHERE product_type = 'subscription' AND amount_paise = 0);
INSERT INTO prices (plan_id, product_type, amount_paise, interval) SELECT id, 'subscription', 14900, 'month' FROM plans WHERE code = 'plus' AND NOT EXISTS (SELECT 1 FROM prices WHERE product_type = 'subscription' AND amount_paise = 14900);
INSERT INTO prices (plan_id, product_type, amount_paise, interval) SELECT id, 'subscription', 119900, 'year' FROM plans WHERE code = 'plus' AND NOT EXISTS (SELECT 1 FROM prices WHERE product_type = 'subscription' AND amount_paise = 119900);
INSERT INTO prices (plan_id, product_type, amount_paise, interval) SELECT id, 'subscription', 29900, 'month' FROM plans WHERE code = 'pro' AND NOT EXISTS (SELECT 1 FROM prices WHERE product_type = 'subscription' AND amount_paise = 29900);
